import { existsSync, readFileSync, readdirSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { DIRS, ensureDirs } from "./config.ts";

export interface Skill {
  name: string;
  description: string;
  body: string;
}

export function listSkills(): Skill[] {
  ensureDirs();
  try {
    return readdirSync(DIRS.skills)
      .filter((f) => f.endsWith(".md"))
      .map((f) => loadSkill(f.replace(/\.md$/, "")))
      .filter((s): s is Skill => s !== null);
  } catch {
    return [];
  }
}

export function loadSkill(name: string): Skill | null {
  const path = join(DIRS.skills, `${name}.md`);
  if (!existsSync(path)) return null;
  const raw = readFileSync(path, "utf8");
  const fm = raw.match(/^---\n([\s\S]*?)\n---\n?([\s\S]*)$/);
  let description = "";
  let body = raw;
  if (fm) {
    const descLine = fm[1].split("\n").find((l) => l.startsWith("description:"));
    description = descLine ? descLine.slice("description:".length).trim() : "";
    body = fm[2].trim();
  }
  return { name, description, body };
}

export function saveSkill(name: string, description: string, body: string): string {
  ensureDirs();
  const safe = name.toLowerCase().replace(/[^a-z0-9-]/g, "-");
  const path = join(DIRS.skills, `${safe}.md`);
  writeFileSync(path, `---\ndescription: ${description}\n---\n\n${body}\n`, { mode: 0o600 });
  return safe;
}

/** Expand a skill invocation: $ARGS placeholder gets the user's arguments. */
export function expandSkill(skill: Skill, args: string): string {
  if (skill.body.includes("$ARGS")) return skill.body.replaceAll("$ARGS", args);
  return args ? `${skill.body}\n\nArguments: ${args}` : skill.body;
}
